CREATE OR REPLACE FUNCTION private.execute_phase3_command(p_user_id uuid, p_command jsonb, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_operation_id text := coalesce(p_command ->> 'operationId', '');
  v_command_type text := coalesce(p_command ->> 'type', '');
  v_payload jsonb := coalesce(p_command -> 'payload', '{}'::jsonb);
  v_request_hash text := encode(
    extensions.digest(convert_to(p_command::text, 'UTF8'), 'sha256'), 'hex'
  );
  v_inserted_count bigint := 0;
  v_existing private.command_operations%rowtype;
  v_root public.member_game_roots%rowtype;
  v_profile public.profiles%rowtype;
  v_result jsonb;
  v_state jsonb;
  v_domain_result jsonb := '{}'::jsonb;
  v_date_text text;
  v_entry_date date;
  v_draft jsonb;
  v_title text;
  v_direction text;
  v_habit_id uuid;
  v_rule_id text;
  v_enabled boolean;
  v_habit public.custom_habits%rowtype;
  v_active_count integer;
begin
  if p_user_id is null then
    return jsonb_build_object('ok', false, 'errorCode', 'AUTH_REQUIRED', 'retryable', false);
  end if;

  if p_command is null
    or jsonb_typeof(p_command) <> 'object'
    or coalesce(p_command ->> 'contractVersion', '') <> '1'
    or v_operation_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'
    or jsonb_typeof(v_payload) <> 'object'
    or v_command_type not in (
      'SAVE_DAILY_DRAFT', 'CREATE_CUSTOM_HABIT', 'UPDATE_CUSTOM_HABIT',
      'REMOVE_CUSTOM_HABIT', 'RESTORE_CUSTOM_HABIT', 'SET_RULE_ENABLED'
    )
  then
    return jsonb_build_object(
      'ok', false, 'errorCode', 'INVALID_PAYLOAD', 'retryable', false,
      'operationId', nullif(v_operation_id, '')
    );
  end if;

  -- Validate the complete intent before reserving an operation or casting values.
  if v_command_type = 'SAVE_DAILY_DRAFT' then
    v_date_text := coalesce(v_payload ->> 'date', '');
    v_draft := v_payload -> 'draft';
    if (select count(*) from jsonb_object_keys(v_payload)) <> 2
      or (v_payload - 'date' - 'draft') <> '{}'::jsonb
      or v_date_text !~ '^\d{4}-\d{2}-\d{2}$'
      or to_char(to_date(v_date_text, 'YYYY-MM-DD'), 'YYYY-MM-DD') <> v_date_text
      or jsonb_typeof(v_draft) <> 'object'
      or (select count(*) from jsonb_object_keys(v_draft)) <> 7
      or (v_draft - 'sleep' - 'water' - 'exercise' - 'study' - 'expense' - 'impulse' - 'sugaryDrinks') <> '{}'::jsonb
      or exists (
        select 1 from jsonb_each(v_draft) item
        where item.value <> 'null'::jsonb and jsonb_typeof(item.value) <> 'number'
      )
    then
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD', 'retryable', false, 'operationId', v_operation_id);
    end if;
    v_entry_date := v_date_text::date;
  elsif v_command_type = 'CREATE_CUSTOM_HABIT' then
    v_title := btrim(coalesce(v_payload ->> 'title', ''));
    v_direction := coalesce(v_payload ->> 'direction', '');
    if (select count(*) from jsonb_object_keys(v_payload)) <> 2
      or (v_payload - 'title' - 'direction') <> '{}'::jsonb
      or char_length(v_title) not between 1 and 80
      or v_direction not in ('good', 'bad')
    then
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD', 'retryable', false, 'operationId', v_operation_id);
    end if;
  elsif v_command_type = 'UPDATE_CUSTOM_HABIT' then
    if coalesce(v_payload ->> 'habitId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or (select count(*) from jsonb_object_keys(v_payload)) not between 2 and 3
      or (v_payload - 'habitId' - 'title' - 'direction') <> '{}'::jsonb
      or not (v_payload ? 'title' or v_payload ? 'direction')
      or (v_payload ? 'title' and char_length(btrim(coalesce(v_payload ->> 'title', ''))) not between 1 and 80)
      or (v_payload ? 'direction' and coalesce(v_payload ->> 'direction', '') not in ('good', 'bad'))
    then
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD', 'retryable', false, 'operationId', v_operation_id);
    end if;
    v_habit_id := (v_payload ->> 'habitId')::uuid;
  elsif v_command_type in ('REMOVE_CUSTOM_HABIT', 'RESTORE_CUSTOM_HABIT') then
    if (select count(*) from jsonb_object_keys(v_payload)) <> 1
      or (v_payload - 'habitId') <> '{}'::jsonb
      or coalesce(v_payload ->> 'habitId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    then
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD', 'retryable', false, 'operationId', v_operation_id);
    end if;
    v_habit_id := (v_payload ->> 'habitId')::uuid;
  elsif v_command_type = 'SET_RULE_ENABLED' then
    v_rule_id := coalesce(v_payload ->> 'ruleId', '');
    if (select count(*) from jsonb_object_keys(v_payload)) <> 2
      or (v_payload - 'ruleId' - 'enabled') <> '{}'::jsonb
      or v_rule_id not in (
        'rule_1', 'rule_2', 'rule_water', 'rule_exercise', 'rule_5', 'rule_3',
        'rule_boss_sleep', 'rule_boss_lazy', 'rule_boss_budget',
        'rule_boss_fried_food', 'rule_4', 'rule_6'
      )
      or jsonb_typeof(v_payload -> 'enabled') <> 'boolean'
    then
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD', 'retryable', false, 'operationId', v_operation_id);
    end if;
    v_enabled := (v_payload ->> 'enabled')::boolean;
  end if;

  -- Phase 6B-2: presence is contract validation; receipt replay still precedes version comparison.
  if p_expected_version is null or p_expected_version < 0 then
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD', 'retryable', false);
  end if;

  insert into private.command_operations (
    user_id, operation_id, command_type, request_hash, status
  ) values (
    p_user_id, v_operation_id, v_command_type, v_request_hash, 'pending'
  ) on conflict (user_id, operation_id) do nothing;
  get diagnostics v_inserted_count = row_count;

  select * into v_existing from private.command_operations
   where user_id = p_user_id and operation_id = v_operation_id for update;

  if v_inserted_count = 0 then
    if v_existing.request_hash <> v_request_hash or v_existing.command_type <> v_command_type then
      return jsonb_build_object('ok', false, 'errorCode', 'OPERATION_ID_REUSED', 'retryable', false, 'operationId', v_operation_id);
    end if;
    if v_existing.status = 'completed' and v_existing.result is not null then
      return v_existing.result || jsonb_build_object('duplicate', true);
    end if;
    return jsonb_build_object('ok', false, 'errorCode', 'OPERATION_IN_PROGRESS', 'retryable', true, 'operationId', v_operation_id);
  end if;

  select * into v_root from public.member_game_roots where user_id = p_user_id for update;
  select * into v_profile from public.profiles where user_id = p_user_id for update;
  if v_root.user_id is null or v_profile.user_id is null then
    delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
    return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND', 'retryable', false, 'operationId', v_operation_id);
  end if;
  if p_expected_version is not null and p_expected_version <> v_root.repository_version then
    delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
    return jsonb_build_object('ok', false, 'errorCode', 'VERSION_CONFLICT', 'retryable', true, 'operationId', v_operation_id, 'currentVersion', v_root.repository_version);
  end if;

  if v_command_type = 'SAVE_DAILY_DRAFT'
    and v_entry_date > (now() at time zone v_profile.timezone)::date
  then
    delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_BUSINESS_DATE', 'retryable', false, 'operationId', v_operation_id);
  end if;

  if v_command_type = 'SAVE_DAILY_DRAFT' then
    if v_entry_date < (now() at time zone v_profile.timezone)::date - 7 then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'BACKFILL_NOT_ALLOWED', 'retryable', false, 'operationId', v_operation_id);
    end if;
    if (v_draft ->> 'sleep')::numeric not between 0 and 24
      or (v_draft ->> 'water')::numeric not between 0 and 100000
      or (v_draft ->> 'exercise')::numeric not between 0 and 1440
      or (v_draft ->> 'study')::numeric not between 0 and 1440
      or (v_draft ->> 'expense')::numeric not between 0 and 1000000000
      or (v_draft ->> 'impulse')::numeric not between 0 and 1000
      or (v_draft ->> 'sugaryDrinks')::numeric not between 0 and 1000
      or coalesce(mod((v_draft ->> 'water')::numeric, 1) <> 0, false)
      or coalesce(mod((v_draft ->> 'exercise')::numeric, 1) <> 0, false)
      or coalesce(mod((v_draft ->> 'study')::numeric, 1) <> 0, false)
      or coalesce(mod((v_draft ->> 'expense')::numeric, 1) <> 0, false)
      or coalesce(mod((v_draft ->> 'impulse')::numeric, 1) <> 0, false)
      or coalesce(mod((v_draft ->> 'sugaryDrinks')::numeric, 1) <> 0, false)
    then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD', 'retryable', false, 'operationId', v_operation_id);
    end if;
    insert into public.daily_drafts (
      user_id, entry_date, sleep, water, exercise, study, expense, impulse, sugary_drinks
    ) values (
      p_user_id, v_entry_date,
      (v_draft ->> 'sleep')::numeric,
      coalesce((v_draft ->> 'water')::integer, 0),
      coalesce((v_draft ->> 'exercise')::integer, 0),
      coalesce((v_draft ->> 'study')::integer, 0),
      (v_draft ->> 'expense')::integer,
      coalesce((v_draft ->> 'impulse')::integer, 0),
      coalesce((v_draft ->> 'sugaryDrinks')::integer, 0)
    ) on conflict (user_id, entry_date) do update set
      sleep = excluded.sleep, water = excluded.water, exercise = excluded.exercise,
      study = excluded.study, expense = excluded.expense, impulse = excluded.impulse,
      sugary_drinks = excluded.sugary_drinks, updated_at = now();
    v_domain_result := jsonb_build_object('date', v_date_text);
  elsif v_command_type = 'CREATE_CUSTOM_HABIT' then
    select count(*) into v_active_count from public.custom_habits where user_id = p_user_id and deleted_at is null;
    if v_active_count >= 50 then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'LIMIT_REACHED', 'retryable', false, 'operationId', v_operation_id);
    end if;
    insert into public.custom_habits(user_id, title, direction)
      values (p_user_id, v_title, v_direction) returning * into v_habit;
    v_domain_result := jsonb_build_object('habitId', v_habit.id);
  elsif v_command_type = 'UPDATE_CUSTOM_HABIT' then
    update public.custom_habits set
      title = case when v_payload ? 'title' then btrim(v_payload ->> 'title') else title end,
      direction = case when v_payload ? 'direction' then v_payload ->> 'direction' else direction end,
      updated_at = now()
    where id = v_habit_id and user_id = p_user_id and deleted_at is null
    returning * into v_habit;
    if v_habit.id is null then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND', 'retryable', false, 'operationId', v_operation_id);
    end if;
    v_domain_result := jsonb_build_object('habitId', v_habit.id);
  elsif v_command_type = 'REMOVE_CUSTOM_HABIT' then
    update public.custom_habits set deleted_at = now(), updated_at = now()
    where id = v_habit_id and user_id = p_user_id and deleted_at is null
    returning * into v_habit;
    if v_habit.id is null then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND', 'retryable', false, 'operationId', v_operation_id);
    end if;
    v_domain_result := jsonb_build_object('habitId', v_habit.id, 'deletedAt', v_habit.deleted_at);
  elsif v_command_type = 'RESTORE_CUSTOM_HABIT' then
    select count(*) into v_active_count from public.custom_habits where user_id = p_user_id and deleted_at is null;
    if v_active_count >= 50 then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'LIMIT_REACHED', 'retryable', false, 'operationId', v_operation_id);
    end if;
    update public.custom_habits set deleted_at = null, updated_at = now()
    where id = v_habit_id and user_id = p_user_id and deleted_at is not null
    returning * into v_habit;
    if v_habit.id is null then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND', 'retryable', false, 'operationId', v_operation_id);
    end if;
    v_domain_result := jsonb_build_object('habitId', v_habit.id);
  elsif v_command_type = 'SET_RULE_ENABLED' then
    insert into public.rule_preferences(user_id, rule_id, enabled)
      values (p_user_id, v_rule_id, v_enabled)
    on conflict (user_id, rule_id) do update set enabled = excluded.enabled, updated_at = now();
    v_domain_result := jsonb_build_object('ruleId', v_rule_id, 'enabled', v_enabled);
  end if;

  update public.member_game_roots
    set repository_version = repository_version + 1, updated_at = now()
    where user_id = p_user_id returning * into v_root;
  v_state := private.member_profile_state(p_user_id);
  v_result := jsonb_build_object(
    'ok', true,
    'operationId', v_operation_id,
    'repositoryVersion', v_root.repository_version,
    'duplicate', false,
    'serverTimestamp', now(),
    'result', v_domain_result,
    'state', v_state
  );
  update private.command_operations set status = 'completed', result = v_result, completed_at = now()
    where user_id = p_user_id and operation_id = v_operation_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.execute_phase4b_command(p_user_id uuid, p_command jsonb, p_expected_version bigint, p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_type text := p_command ->> 'type';
  v_operation_id text := p_command ->> 'operationId';
  v_payload jsonb := p_command -> 'payload';
  v_business_date date;
  v_today date := (now() at time zone 'Asia/Taipei')::date;
  v_request_hash text;
  v_reserved jsonb;
  v_completed jsonb;
  v_result jsonb := '{}'::jsonb;
  v_player public.player_states%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_deltas jsonb;
  v_resource record;
  v_balance bigint;
  v_reason text;
  v_source_type text;
  v_source_id text;
  v_event public.habit_events%rowtype;
  v_entry public.daily_entries%rowtype;
  v_revision public.daily_entry_revisions%rowtype;
  v_previous_revision public.daily_entry_revisions%rowtype;
  v_previous_operation private.command_operations%rowtype;
  v_old_ledger public.resource_ledger%rowtype;
  v_status jsonb;
  v_achievement text;
  v_boss jsonb;
  v_boss_definition jsonb;
  v_encounter public.boss_encounters%rowtype;
  v_boss_action_id uuid;
  v_new_hp bigint;
  v_operation_version bigint;
  v_current_version bigint;
  v_component bigint;
  v_running_balance bigint;
begin
  if p_user_id is null or p_command is null or p_plan is null
    or jsonb_typeof(p_command) <> 'object' or jsonb_typeof(p_plan) <> 'object'
    or v_type not in ('REPORT_HABIT_EVENT', 'REVERSE_HABIT_EVENT', 'SUBMIT_DAILY_ENTRY')
    or p_command ->> 'contractVersion' <> '1'
    or v_operation_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'
    or p_expected_version is null or p_expected_version < 0
    or p_command #>> '{context,timeZone}' <> 'Asia/Taipei'
    or p_command #>> '{context,businessDate}' !~ '^\d{4}-\d{2}-\d{2}$' then
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
  end if;
  begin
    v_business_date := (p_command #>> '{context,businessDate}')::date;
  exception when others then
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_BUSINESS_DATE');
  end;
  if v_type in ('REPORT_HABIT_EVENT', 'REVERSE_HABIT_EVENT') and v_business_date <> v_today then
    return jsonb_build_object('ok', false, 'errorCode', 'HABIT_EVENT_NOT_TODAY');
  end if;
  if v_type = 'SUBMIT_DAILY_ENTRY' then
    if v_business_date > v_today then return jsonb_build_object('ok', false, 'errorCode', 'INVALID_BUSINESS_DATE'); end if;
    if v_business_date < v_today - 7 then return jsonb_build_object('ok', false, 'errorCode', 'BACKFILL_NOT_ALLOWED'); end if;
  end if;
  if (v_type = 'REPORT_HABIT_EVENT' and p_plan ->> 'kind' <> 'habit_event')
    or (v_type = 'REVERSE_HABIT_EVENT' and p_plan ->> 'kind' <> 'habit_reversal')
    or (v_type = 'SUBMIT_DAILY_ENTRY' and p_plan ->> 'kind' <> 'daily_settlement')
    or coalesce(p_plan ->> 'businessDate', v_business_date::text) <> v_business_date::text then
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
  end if;

  v_request_hash := encode(extensions.digest(convert_to(p_command::text, 'UTF8'), 'sha256'), 'hex');
  v_reserved := private.phase4_reserve_operation(
    p_user_id, v_operation_id, v_type, v_request_hash, p_expected_version
  );
  if v_reserved ->> 'ok' <> 'true' then return v_reserved; end if;
  if coalesce((v_reserved ->> 'duplicate')::boolean, false) then
    select repository_version into v_current_version from public.member_game_roots where user_id = p_user_id;
    v_operation_version := coalesce((v_reserved ->> 'repositoryVersion')::bigint, v_current_version);
    return v_reserved || jsonb_build_object(
      'operationId', v_operation_id, 'operationRepositoryVersion', v_operation_version,
      'repositoryVersion', v_current_version, 'state', private.phase4b_state(p_user_id),
      'serverTimestamp', now(), 'duplicate', true
    );
  end if;

  select * into v_player from public.player_states where user_id = p_user_id for update;

  if v_type = 'REVERSE_HABIT_EVENT' then
    select * into v_event from public.habit_events
      where id = (v_payload ->> 'eventId')::uuid and user_id = p_user_id for update;
    if not found then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'HABIT_EVENT_NOT_FOUND');
    end if;
    select * into v_previous_operation from private.command_operations
      where user_id = p_user_id and operation_id = v_event.source_operation_id;
    if v_event.reversed_at is not null
      or coalesce((v_previous_operation.result ->> 'repositoryVersion')::bigint, -1) <> p_expected_version
      or coalesce((v_event.policy_snapshot #>> '{resource,died}')::boolean, false)
      or exists (select 1 from public.boss_actions where user_id = p_user_id and source_type = 'habit_event' and source_id = v_event.id::text)
      or exists (select 1 from public.status_effects where user_id = p_user_id and source_type = 'habit_event' and source_id = v_event.id::text)
      or exists (select 1 from public.player_achievements where user_id = p_user_id and target_snapshot ->> 'sourceOperationId' = v_event.source_operation_id) then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'REVERSAL_BLOCKED');
    end if;
    v_before := v_event.policy_snapshot #> '{resource,before}';
    v_after := v_event.policy_snapshot #> '{resource,after}';
    if v_before is null or v_after is null
      or v_player.total_xp <> (v_after ->> 'totalXp')::bigint
      or v_player.hp <> (v_after ->> 'hp')::bigint
      or v_player.gold <> (v_after ->> 'gold')::bigint
      or v_player.gems <> (v_after ->> 'gems')::bigint then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'REVERSAL_BLOCKED');
    end if;
    update public.habit_events set reversed_at = now(), reversed_by_operation_id = v_operation_id,
      reversal_reason = 'user_requested' where id = v_event.id;
    for v_old_ledger in select * from public.resource_ledger
      where user_id = p_user_id and operation_id = v_event.source_operation_id order by id
    loop
      v_balance := case v_old_ledger.resource_type
        when 'xp' then (v_before ->> 'totalXp')::bigint
        when 'hp' then (v_before ->> 'hp')::bigint
        when 'gold' then (v_before ->> 'gold')::bigint
        when 'gems' then (v_before ->> 'gems')::bigint
        else (v_before #>> array['baseStats', v_old_ledger.resource_type])::bigint end;
      insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
        source_type, source_id, operation_id, reverses_ledger_id)
      values (p_user_id, v_old_ledger.resource_type, -v_old_ledger.delta, v_balance, 'reversal',
        'reversal', v_old_ledger.id::text, v_operation_id, v_old_ledger.id);
    end loop;
    update public.player_states set
      total_xp = (v_before ->> 'totalXp')::bigint, hp = (v_before ->> 'hp')::bigint,
      gold = (v_before ->> 'gold')::bigint, gems = (v_before ->> 'gems')::bigint,
      base_health = (v_before #>> '{baseStats,health}')::integer,
      base_energy = (v_before #>> '{baseStats,energy}')::integer,
      base_wealth = (v_before #>> '{baseStats,wealth}')::integer,
      base_growth = (v_before #>> '{baseStats,growth}')::integer, updated_at = now()
    where user_id = p_user_id;
    v_result := jsonb_build_object('eventId', v_event.id, 'reversed', true);
  else
    v_before := p_plan #> '{resource,before}';
    v_after := p_plan #> '{resource,after}';
    v_deltas := p_plan #> '{resource,deltas}';
    if v_before is null or v_after is null or v_deltas is null
      or jsonb_typeof(v_before) <> 'object' or jsonb_typeof(v_after) <> 'object'
      or jsonb_typeof(v_deltas) <> 'object' then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
    end if;

    if v_type = 'REPORT_HABIT_EVENT' then
      if v_player.total_xp <> (v_before ->> 'totalXp')::bigint
        or v_player.hp <> (v_before ->> 'hp')::bigint
        or v_player.gold <> (v_before ->> 'gold')::bigint
        or v_player.gems <> (v_before ->> 'gems')::bigint then
        delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
        return jsonb_build_object('ok', false, 'errorCode', 'VERSION_CONFLICT');
      end if;
      insert into public.habit_events(
        user_id, business_date, habit_kind, system_key, custom_habit_id, direction,
        title_snapshot, policy_snapshot, source_operation_id, occurred_at
      ) values (
        p_user_id, v_business_date, p_plan #>> '{habit,kind}', nullif(p_plan #>> '{habit,systemKey}', ''),
        nullif(p_plan #>> '{habit,customHabitId}', '')::uuid, p_plan #>> '{habit,direction}',
        p_plan #>> '{habit,title}', (p_plan #> '{habit,policy}') || jsonb_build_object('resource', p_plan -> 'resource'),
        v_operation_id, now()
      ) returning * into v_event;
      v_source_type := 'habit_event'; v_source_id := v_event.id::text;
      v_reason := case when v_event.direction = 'good' then 'habit_reward' else 'habit_damage' end;
      v_result := jsonb_build_object('eventId', v_event.id, 'rewardGranted',
        coalesce((p_plan #>> '{habit,policy,rewardGranted}')::boolean, false));
    else
      select * into v_entry from public.daily_entries
        where user_id = p_user_id and business_date = v_business_date for update;
      if found then
        select * into v_previous_revision from public.daily_entry_revisions
          where daily_entry_id = v_entry.id and revision_no = v_entry.current_revision for update;
        select * into v_previous_operation from private.command_operations
          where user_id = p_user_id and operation_id = v_previous_revision.operation_id;
        if private.phase4b_has_gameplay_dependency(p_user_id, v_previous_revision.operation_id)
          or coalesce((v_previous_revision.settlement_snapshot #>> '{resource,died}')::boolean, false)
          or jsonb_array_length(coalesce(v_previous_revision.settlement_snapshot -> 'statuses', '[]'::jsonb)) > 0
          or v_previous_revision.settlement_snapshot -> 'boss' <> 'null'::jsonb
          or jsonb_array_length(coalesce(v_previous_revision.settlement_snapshot -> 'achievementEvents', '[]'::jsonb)) > 0 then
          delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
          return jsonb_build_object('ok', false, 'errorCode', 'DAILY_REVISION_BLOCKED');
        end if;
        if v_player.total_xp <> (p_plan #>> '{correction,expectedPlayerAfter,totalXp}')::bigint
          or v_player.hp <> (p_plan #>> '{correction,expectedPlayerAfter,hp}')::bigint
          or v_player.gold <> (p_plan #>> '{correction,expectedPlayerAfter,gold}')::bigint
          or v_player.gems <> (p_plan #>> '{correction,expectedPlayerAfter,gems}')::bigint then
          delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
          return jsonb_build_object('ok', false, 'errorCode', 'DAILY_REVISION_BLOCKED');
        end if;
        for v_old_ledger in select * from public.resource_ledger
          where user_id = p_user_id and operation_id = v_previous_revision.operation_id order by id
        loop
          v_balance := case v_old_ledger.resource_type
            when 'xp' then (v_before ->> 'totalXp')::bigint
            when 'hp' then (v_before ->> 'hp')::bigint
            when 'gold' then (v_before ->> 'gold')::bigint
            when 'gems' then (v_before ->> 'gems')::bigint
            else (v_before #>> array['baseStats', v_old_ledger.resource_type])::bigint end;
          insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
            source_type, source_id, operation_id, reverses_ledger_id)
          values (p_user_id, v_old_ledger.resource_type, -v_old_ledger.delta, v_balance, 'reversal',
            'reversal', v_old_ledger.id::text, v_operation_id, v_old_ledger.id);
        end loop;
        v_entry.current_revision := v_entry.current_revision + 1;
        update public.daily_entries set current_revision = v_entry.current_revision,
          sleep = (v_payload ->> 'sleep')::numeric, water = (v_payload ->> 'water')::integer,
          exercise = (v_payload ->> 'exercise')::integer, study = (v_payload ->> 'study')::integer,
          expense = (v_payload ->> 'expense')::bigint, impulse = (v_payload ->> 'impulse')::integer,
          sugary_drinks = (v_payload ->> 'sugaryDrinks')::integer,
          effective_input = p_plan -> 'effectiveInput', settlement_snapshot = p_plan,
          budget_snapshot = (p_plan ->> 'budgetSnapshot')::bigint, settled_at = now(), updated_at = now()
        where id = v_entry.id;
      else
        if v_player.total_xp <> (v_before ->> 'totalXp')::bigint
          or v_player.hp <> (v_before ->> 'hp')::bigint
          or v_player.gold <> (v_before ->> 'gold')::bigint
          or v_player.gems <> (v_before ->> 'gems')::bigint then
          delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
          return jsonb_build_object('ok', false, 'errorCode', 'VERSION_CONFLICT');
        end if;
        insert into public.daily_entries(
          user_id, business_date, current_revision, sleep, water, exercise, study, expense, impulse,
          sugary_drinks, timezone, budget_snapshot, effective_input, settlement_snapshot, settled_at
        ) values (
          p_user_id, v_business_date, 1, (v_payload ->> 'sleep')::numeric,
          (v_payload ->> 'water')::integer, (v_payload ->> 'exercise')::integer,
          (v_payload ->> 'study')::integer, (v_payload ->> 'expense')::bigint,
          (v_payload ->> 'impulse')::integer, (v_payload ->> 'sugaryDrinks')::integer,
          'Asia/Taipei', (p_plan ->> 'budgetSnapshot')::bigint,
          p_plan -> 'effectiveInput', p_plan, now()
        ) returning * into v_entry;
      end if;
      insert into public.daily_entry_revisions(
        user_id, daily_entry_id, revision_no, correction_of_revision, raw_input,
        effective_input, settlement_snapshot, operation_id
      ) values (
        p_user_id, v_entry.id, v_entry.current_revision,
        case when v_entry.current_revision > 1 then v_entry.current_revision - 1 else null end,
        v_payload, p_plan -> 'effectiveInput', p_plan, v_operation_id
      ) returning * into v_revision;
      v_source_type := 'daily_entry_revision'; v_source_id := v_revision.id::text;
      v_reason := 'daily_reward';
      v_result := jsonb_build_object(
        'entryId', v_entry.id, 'revision', v_entry.current_revision,
        'completedRuleIds', p_plan -> 'completedRuleIds', 'failedRuleIds', p_plan -> 'failedRuleIds',
        'critical', p_plan -> 'critical'
      );
    end if;

    update public.player_states set
      total_xp = (v_after ->> 'totalXp')::bigint, hp = (v_after ->> 'hp')::bigint,
      gold = (v_after ->> 'gold')::bigint, gems = (v_after ->> 'gems')::bigint,
      base_health = (v_after #>> '{baseStats,health}')::integer,
      base_energy = (v_after #>> '{baseStats,energy}')::integer,
      base_wealth = (v_after #>> '{baseStats,wealth}')::integer,
      base_growth = (v_after #>> '{baseStats,growth}')::integer, updated_at = now()
    where user_id = p_user_id;

    for v_resource in select key, value from jsonb_each_text(v_deltas)
    loop
      v_balance := case v_resource.key
        when 'xp' then (v_after ->> 'totalXp')::bigint
        when 'hp' then (v_after ->> 'hp')::bigint
        when 'gold' then (v_after ->> 'gold')::bigint
        when 'gems' then (v_after ->> 'gems')::bigint
        else (v_after #>> array['baseStats', v_resource.key])::bigint end;
      if v_resource.key in ('gold', 'gems') then
        v_running_balance := case v_resource.key
          when 'gold' then (v_before ->> 'gold')::bigint
          else (v_before ->> 'gems')::bigint end;
        if v_type = 'SUBMIT_DAILY_ENTRY' then
          v_component := coalesce((p_plan #>> array['rewardBreakdown', 'daily', v_resource.key])::bigint, 0);
          if v_component <> 0 then
            v_running_balance := v_running_balance + v_component;
            insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
              source_type, source_id, operation_id)
            values (p_user_id, v_resource.key, v_component, v_running_balance, 'daily_reward',
              v_source_type, v_source_id, v_operation_id);
          end if;
          v_component := coalesce((p_plan #>> array['rewardBreakdown', 'boss', v_resource.key])::bigint, 0);
          if v_component <> 0 then
            v_running_balance := v_running_balance + v_component;
            insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
              source_type, source_id, operation_id)
            values (p_user_id, v_resource.key, v_component, v_running_balance, 'boss_reward',
              'boss_action', coalesce(p_plan #>> '{boss,encounterId}', v_source_id), v_operation_id);
          end if;
          if v_resource.key = 'gems' then
            for v_achievement in
              select jsonb_array_elements_text(coalesce(p_plan -> 'achievementEvents', '[]'::jsonb))
            loop
              v_component := case
                when v_achievement in ('exercise_streak_3', 'boss_slayer') then 5
                else 0
              end;
              if v_component <> 0 then
                v_running_balance := v_running_balance + v_component;
                insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
                  source_type, source_id, operation_id)
                values (p_user_id, v_resource.key, v_component, v_running_balance, 'achievement_reward',
                  'achievement', v_achievement, v_operation_id);
              end if;
            end loop;
          end if;
        else
          v_component := coalesce((p_plan #>> array['habit', 'policy', 'effects', v_resource.key])::bigint, 0);
          if v_component <> 0 then
            v_running_balance := v_running_balance + v_component;
            insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
              source_type, source_id, operation_id)
            values (p_user_id, v_resource.key, v_component, v_running_balance, v_reason,
              v_source_type, v_source_id, v_operation_id);
          end if;
        end if;
        if v_resource.key = 'gold' and coalesce((p_plan #>> '{resource,goldLost}')::bigint, 0) > 0 then
          v_component := -((p_plan #>> '{resource,goldLost}')::bigint);
          v_running_balance := v_running_balance + v_component;
          insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
            source_type, source_id, operation_id)
          values (p_user_id, 'gold', v_component, v_running_balance, 'death_penalty',
            'death', v_source_id, v_operation_id);
        end if;
        if v_running_balance <> v_balance then
          raise exception 'PHASE4_RESOURCE_BREAKDOWN_MISMATCH';
        end if;
      elsif v_resource.value::bigint <> 0 then
        insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
          source_type, source_id, operation_id)
        values (p_user_id, v_resource.key, v_resource.value::bigint, v_balance,
          case when v_resource.value::bigint < 0 then
            case when v_type = 'REPORT_HABIT_EVENT' then 'habit_damage' else 'daily_failure' end
          else v_reason end,
          v_source_type, v_source_id, v_operation_id);
      end if;
    end loop;

    if coalesce((p_plan #>> '{resource,died}')::boolean, false) then
      update public.status_effects set state = 'cleared', state_changed_at = now()
        where user_id = p_user_id and state = 'active';
    end if;

    for v_status in select value from jsonb_array_elements(coalesce(p_plan -> 'statuses', '[]'::jsonb))
    loop
      update public.status_effects set state = 'cleared', state_changed_at = now()
        where user_id = p_user_id and effect_key = v_status ->> 'key' and state = 'active';
      insert into public.status_effects(
        user_id, effect_key, effect_type, title_snapshot, modifier_snapshot,
        applied_on, expires_on, state, source_type, source_id, definition_version
      ) values (
        p_user_id, v_status ->> 'key', v_status ->> 'effectType', v_status ->> 'title',
        coalesce(v_status -> 'modifiers', '{}'::jsonb), (v_status ->> 'appliedOn')::date,
        (v_status ->> 'expiresOn')::date, v_status ->> 'state', v_source_type, v_source_id,
        v_status ->> 'definitionVersion'
      );
    end loop;

    for v_achievement in select jsonb_array_elements_text(coalesce(p_plan -> 'achievementEvents', '[]'::jsonb))
    loop
      insert into public.player_achievements(
        user_id, achievement_code, target_snapshot, reward_snapshot, unlocked_at,
        reward_state, reward_granted_at, reward_operation_id
      ) values (
        p_user_id, v_achievement,
        jsonb_build_object('sourceOperationId', v_operation_id),
        case
          when v_achievement = 'exercise_streak_3'
            then jsonb_build_object('gems', 5, 'status', 'vitality')
          when v_achievement = 'boss_slayer'
            then jsonb_build_object('gems', 5)
          else '{}'::jsonb
        end,
        now(), 'granted', now(), v_operation_id
      ) on conflict (user_id, achievement_code) do nothing;
    end loop;

    v_boss := p_plan -> 'boss';
    if v_boss is not null and v_boss <> 'null'::jsonb then
      if v_boss ->> 'action' = 'summon' then
        v_boss_definition := p_plan #> array['definitions'];
        insert into public.boss_encounters(
          user_id, boss_key, incident_key, name_snapshot, max_hp, hp,
          challenge_snapshot, reward_snapshot, summoned_on
        ) values (
          p_user_id, v_boss ->> 'bossKey', (v_boss ->> 'bossKey') || ':' || v_business_date::text,
          case v_boss ->> 'bossKey'
            when 'sleep-nightmare' then '睡眠夢魘' when 'budget-vampire' then '預算吸血鬼'
            when 'fried-food-beast' then '油炸暴食獸' when 'laziness-beast' then '怠惰巨獸'
            else '糖分魔獸' end,
          100, 100, jsonb_build_object('targetDays', 3), jsonb_build_object('gold', 150, 'gems', 3),
          v_business_date
        ) on conflict (user_id, incident_key) do nothing returning * into v_encounter;
        if v_encounter.id is not null then
          insert into public.boss_actions(user_id, encounter_id, action_type, business_date,
            source_type, source_id, operation_id, action_snapshot)
          values (p_user_id, v_encounter.id, 'summon', v_business_date,
            v_source_type, v_source_id, v_operation_id, v_boss);
        end if;
      elsif v_boss ->> 'action' = 'progress' then
        select * into v_encounter from public.boss_encounters
          where id = (v_boss ->> 'encounterId')::uuid and user_id = p_user_id and state = 'active' for update;
        if found then
          v_new_hp := greatest(0, v_encounter.hp - (v_boss ->> 'damage')::bigint);
          insert into public.boss_actions(user_id, encounter_id, action_type, business_date,
            damage, progress_delta, source_type, source_id, operation_id, action_snapshot)
          values (p_user_id, v_encounter.id, 'progress', v_business_date,
            (v_boss ->> 'damage')::bigint, case when (v_boss ->> 'matched')::boolean then 1 else 0 end,
            v_source_type, v_source_id, v_operation_id, v_boss) returning id into v_boss_action_id;
          update public.boss_encounters set hp = v_new_hp,
            state = case when v_new_hp = 0 then 'defeated' else 'active' end,
            defeated_at = case when v_new_hp = 0 then now() else null end,
            reward_granted_at = case when v_new_hp = 0 then now() else null end,
            reward_operation_id = case when v_new_hp = 0 then v_operation_id else null end,
            updated_at = now() where id = v_encounter.id;
          if v_new_hp = 0 then
            insert into public.boss_actions(user_id, encounter_id, action_type, business_date,
              source_type, source_id, operation_id, action_snapshot)
            values (p_user_id, v_encounter.id, 'defeat', v_business_date,
              v_source_type, v_source_id, v_operation_id, v_boss);
            insert into public.boss_actions(user_id, encounter_id, action_type, business_date,
              source_type, source_id, operation_id, action_snapshot)
            values (p_user_id, v_encounter.id, 'reward', v_business_date,
              'boss_encounter', v_encounter.id::text, v_operation_id, v_encounter.reward_snapshot);
          end if;
        end if;
      end if;
    end if;
  end if;

  v_completed := private.phase4_complete_operation(
    p_user_id, v_operation_id,
    jsonb_build_object('operationId', v_operation_id, 'result', v_result, 'serverTimestamp', now())
  );
  if v_completed ->> 'ok' <> 'true' then return v_completed; end if;
  v_operation_version := (v_completed ->> 'repositoryVersion')::bigint;
  return v_completed || jsonb_build_object(
    'operationRepositoryVersion', v_operation_version,
    'state', private.phase4b_state(p_user_id), 'serverTimestamp', now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.execute_phase5b_economy_command(p_user_id uuid, p_command jsonb, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_type text := p_command ->> 'type';
  v_operation_id text := p_command ->> 'operationId';
  v_payload jsonb := p_command -> 'payload';
  v_request_hash text;
  v_reserved jsonb;
  v_completed jsonb;
  v_operation_version bigint;
  v_current_version bigint;
  v_result jsonb := '{}'::jsonb;
  v_catalog public.item_catalog%rowtype;
  v_player public.player_states%rowtype;
  v_inventory public.player_inventory%rowtype;
  v_ticket public.player_reward_tickets%rowtype;
  v_base_wealth bigint;
  v_discount numeric;
  v_final_price bigint;
  v_heal bigint;
  v_max_hp bigint;
  v_transaction_id uuid := gen_random_uuid();
  v_ticket_id uuid := gen_random_uuid();
  v_existing_item text;
  v_slot text;
  v_keys text[];
begin
  if p_user_id is null or p_command is null or jsonb_typeof(p_command) <> 'object'
    or v_type not in ('PURCHASE_ITEM', 'USE_ITEM', 'EQUIP_ITEM', 'UNEQUIP_ITEM',
      'REDEEM_REWARD_TICKET', 'USE_REWARD_TICKET', 'REVERSE_REWARD_TICKET')
    or p_command ->> 'contractVersion' <> '1'
    or v_operation_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'
    or p_expected_version is null or p_expected_version < 0
    or jsonb_typeof(v_payload) <> 'object' then
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
  end if;

  -- Phase 6B-2: require the catalog version before reservation. No client price authority.
  if v_type in ('PURCHASE_ITEM', 'REDEEM_REWARD_TICKET') and not (
    case when jsonb_typeof(v_payload -> 'seenCatalogVersion') = 'number'
      and (v_payload ->> 'seenCatalogVersion') ~ '^[1-9][0-9]*$'
    then (v_payload ->> 'seenCatalogVersion')::numeric <= 9007199254740991
    else false end
  ) then
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
  end if;

  select array_agg(key order by key) into v_keys from jsonb_object_keys(v_payload) key;
  if v_type in ('PURCHASE_ITEM', 'REDEEM_REWARD_TICKET') then
    if not ((v_keys = array[case when v_type = 'PURCHASE_ITEM' then 'itemKey' else 'ticketKey' end])
      or (v_keys = case
        when v_type = 'PURCHASE_ITEM' then array['itemKey', 'seenCatalogVersion']
        else array['seenCatalogVersion', 'ticketKey']
      end))
      or coalesce(v_payload ->> case when v_type = 'PURCHASE_ITEM' then 'itemKey' else 'ticketKey' end, '')
        !~ '^[a-z][a-z0-9_]{1,63}$'
      or (v_payload ? 'seenCatalogVersion' and (v_payload ->> 'seenCatalogVersion') !~ '^[1-9][0-9]*$') then
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
    end if;
  elsif v_type in ('USE_ITEM', 'EQUIP_ITEM') then
    if v_keys <> array['itemKey'] or coalesce(v_payload ->> 'itemKey', '') !~ '^[a-z][a-z0-9_]{1,63}$' then
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
    end if;
  elsif v_type = 'UNEQUIP_ITEM' then
    if v_keys <> array['slot'] or v_payload ->> 'slot' not in ('weapon', 'armor', 'pet') then
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
    end if;
  else
    if v_keys <> array['ticketInstanceId']
      or coalesce(v_payload ->> 'ticketInstanceId', '') !~ '^[0-9a-fA-F-]{36}$' then
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
    end if;
  end if;

  v_request_hash := encode(extensions.digest(convert_to(p_command::text, 'UTF8'), 'sha256'), 'hex');
  v_reserved := private.phase4_reserve_operation(
    p_user_id, v_operation_id, v_type, v_request_hash, p_expected_version
  );
  if v_reserved ->> 'ok' <> 'true' then return v_reserved; end if;
  if coalesce((v_reserved ->> 'duplicate')::boolean, false) then
    select repository_version into v_current_version
      from public.member_game_roots where user_id = p_user_id;
    v_operation_version := coalesce((v_reserved ->> 'repositoryVersion')::bigint, v_current_version);
    return v_reserved || jsonb_build_object(
      'operationId', v_operation_id,
      'operationRepositoryVersion', v_operation_version,
      'repositoryVersion', v_current_version,
      'state', private.phase4b_state(p_user_id) || private.phase5b_economy_state(p_user_id),
      'serverTimestamp', now(), 'duplicate', true
    );
  end if;

  select * into v_player from public.player_states where user_id = p_user_id for update;

  if v_type in ('PURCHASE_ITEM', 'REDEEM_REWARD_TICKET') then
    select * into v_catalog from public.item_catalog
      where item_key = v_payload ->> case when v_type = 'PURCHASE_ITEM' then 'itemKey' else 'ticketKey' end
      for share;
    if not found then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_FOUND');
    end if;
    if not v_catalog.active then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_AVAILABLE');
    end if;
    if v_payload ? 'seenCatalogVersion'
      and (v_payload ->> 'seenCatalogVersion')::bigint <> v_catalog.catalog_version then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'CATALOG_CHANGED');
    end if;
  end if;

  if v_type = 'PURCHASE_ITEM' then
    if v_catalog.item_type = 'reward_ticket' or v_catalog.currency_type <> 'gold' then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_AVAILABLE');
    end if;
    v_base_wealth := v_player.base_wealth;
    v_discount := least(v_base_wealth * 0.01, 0.20);
    v_final_price := floor(v_catalog.base_price * (1 - v_discount));
    if v_player.gold < v_final_price then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'INSUFFICIENT_RESOURCE');
    end if;
    select * into v_inventory from public.player_inventory
      where user_id = p_user_id and item_key = v_catalog.item_key for update;
    if v_catalog.item_type = 'potion' and found and v_inventory.quantity >= 99 then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'INVENTORY_LIMIT_REACHED');
    end if;
    if v_catalog.item_type in ('weapon', 'armor', 'pet') and found then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_ALREADY_OWNED');
    end if;
    update public.player_states set gold = gold - v_final_price, updated_at = now() where user_id = p_user_id;
    insert into public.player_inventory(user_id, item_key, quantity)
      values (p_user_id, v_catalog.item_key, 1)
      on conflict (user_id, item_key) do update
      set quantity = public.player_inventory.quantity + 1, updated_at = now();
    insert into public.economy_transactions(
      id, user_id, operation_id, transaction_type, item_key, currency_type, currency_delta,
      base_price_snapshot, discount_snapshot, paid_amount_snapshot, item_name_snapshot,
      catalog_version_snapshot, detail_snapshot
    ) values (
      v_transaction_id, p_user_id, v_operation_id, 'purchase_item', v_catalog.item_key,
      'gold', -v_final_price, v_catalog.base_price,
      jsonb_build_object('baseWealth', v_base_wealth, 'rate', v_discount), v_final_price,
      v_catalog.display_name, v_catalog.catalog_version,
      jsonb_build_object('itemType', v_catalog.item_type, 'effectKey', v_catalog.effect_key)
    );
    insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
      source_type, source_id, operation_id)
    values (p_user_id, 'gold', -v_final_price, v_player.gold - v_final_price, 'item_purchase',
      'economy_transaction', v_transaction_id::text, v_operation_id);
    v_result := jsonb_build_object('transactionId', v_transaction_id, 'itemKey', v_catalog.item_key,
      'quantity', coalesce(v_inventory.quantity, 0) + 1, 'paidAmount', v_final_price,
      'currency', 'gold', 'catalogVersion', v_catalog.catalog_version);

  elsif v_type = 'USE_ITEM' then
    select * into v_catalog from public.item_catalog
      where item_key = v_payload ->> 'itemKey' and active for share;
    if not found then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_FOUND');
    end if;
    if v_catalog.item_type <> 'potion' or not v_catalog.usable then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_USABLE');
    end if;
    select * into v_inventory from public.player_inventory
      where user_id = p_user_id and item_key = v_catalog.item_key for update;
    if not found then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_OWNED');
    end if;
    v_max_hp := private.max_hp_v1(v_player.total_xp);
    if v_player.hp >= v_max_hp then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'HP_ALREADY_FULL');
    end if;
    v_heal := least(coalesce((v_catalog.member_effects ->> 'healAmount')::bigint, 0), v_max_hp - v_player.hp);
    if v_heal <= 0 then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_USABLE');
    end if;
    update public.player_states set hp = hp + v_heal, updated_at = now() where user_id = p_user_id;
    if v_inventory.quantity = 1 then
      delete from public.player_inventory where user_id = p_user_id and item_key = v_catalog.item_key;
    else
      update public.player_inventory set quantity = quantity - 1, updated_at = now()
        where user_id = p_user_id and item_key = v_catalog.item_key;
    end if;
    insert into public.economy_transactions(id, user_id, operation_id, transaction_type,
      item_key, item_name_snapshot, catalog_version_snapshot, detail_snapshot)
    values (v_transaction_id, p_user_id, v_operation_id, 'use_item', v_catalog.item_key,
      v_catalog.display_name, v_catalog.catalog_version,
      jsonb_build_object('healAmount', v_heal, 'hpBefore', v_player.hp, 'hpAfter', v_player.hp + v_heal));
    insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
      source_type, source_id, operation_id)
    values (p_user_id, 'hp', v_heal, v_player.hp + v_heal, 'item_use',
      'economy_transaction', v_transaction_id::text, v_operation_id);
    v_result := jsonb_build_object('transactionId', v_transaction_id, 'itemKey', v_catalog.item_key,
      'healed', v_heal, 'hp', v_player.hp + v_heal, 'maxHp', v_max_hp);

  elsif v_type = 'EQUIP_ITEM' then
    select * into v_catalog from public.item_catalog
      where item_key = v_payload ->> 'itemKey' and active for share;
    if not found then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_FOUND');
    end if;
    if not v_catalog.equippable or v_catalog.equipment_slot not in ('weapon', 'armor', 'pet') then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_EQUIPPABLE');
    end if;
    select * into v_inventory from public.player_inventory
      where user_id = p_user_id and item_key = v_catalog.item_key for update;
    if not found then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_OWNED');
    end if;
    v_slot := v_catalog.equipment_slot;
    select item_key into v_existing_item from public.player_equipment
      where user_id = p_user_id and slot = v_slot for update;
    insert into public.player_equipment(user_id, slot, item_key)
      values (p_user_id, v_slot, v_catalog.item_key)
      on conflict (user_id, slot) do update
      set item_key = excluded.item_key, equipped_at = now(), updated_at = now();
    insert into public.economy_transactions(id, user_id, operation_id, transaction_type,
      item_key, item_name_snapshot, catalog_version_snapshot, detail_snapshot)
    values (v_transaction_id, p_user_id, v_operation_id, 'equip_item', v_catalog.item_key,
      v_catalog.display_name, v_catalog.catalog_version,
      jsonb_build_object('slot', v_slot, 'previousItemKey', v_existing_item,
        'equipmentModifiers', v_catalog.equipment_modifiers, 'memberEffects', v_catalog.member_effects));
    v_result := jsonb_build_object('transactionId', v_transaction_id, 'itemKey', v_catalog.item_key,
      'slot', v_slot, 'previousItemKey', v_existing_item);

  elsif v_type = 'UNEQUIP_ITEM' then
    v_slot := v_payload ->> 'slot';
    select item_key into v_existing_item from public.player_equipment
      where user_id = p_user_id and slot = v_slot for update;
    if not found then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_OWNED');
    end if;
    delete from public.player_equipment where user_id = p_user_id and slot = v_slot;
    select * into v_catalog from public.item_catalog where item_key = v_existing_item;
    insert into public.economy_transactions(id, user_id, operation_id, transaction_type,
      item_key, item_name_snapshot, catalog_version_snapshot, detail_snapshot)
    values (v_transaction_id, p_user_id, v_operation_id, 'unequip_item', v_existing_item,
      v_catalog.display_name, v_catalog.catalog_version, jsonb_build_object('slot', v_slot));
    v_result := jsonb_build_object('transactionId', v_transaction_id, 'itemKey', v_existing_item,
      'slot', v_slot, 'unequipped', true);

  elsif v_type = 'REDEEM_REWARD_TICKET' then
    if v_catalog.item_type <> 'reward_ticket' or v_catalog.currency_type <> 'gems' then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'ITEM_NOT_AVAILABLE');
    end if;
    if v_player.gems < v_catalog.base_price then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'INSUFFICIENT_RESOURCE');
    end if;
    update public.player_states set gems = gems - v_catalog.base_price, updated_at = now() where user_id = p_user_id;
    insert into public.economy_transactions(
      id, user_id, operation_id, transaction_type, item_key, ticket_id,
      currency_type, currency_delta, base_price_snapshot, paid_amount_snapshot,
      item_name_snapshot, catalog_version_snapshot, detail_snapshot
    ) values (
      v_transaction_id, p_user_id, v_operation_id, 'redeem_reward_ticket', v_catalog.item_key, v_ticket_id,
      'gems', -v_catalog.base_price, v_catalog.base_price, v_catalog.base_price,
      v_catalog.display_name, v_catalog.catalog_version,
      jsonb_build_object('effectKey', v_catalog.effect_key)
    );
    insert into public.player_reward_tickets(
      id, user_id, ticket_key, name_snapshot, gem_cost_snapshot,
      catalog_version_snapshot, source_operation_id, acquisition_transaction_id
    ) values (
      v_ticket_id, p_user_id, v_catalog.item_key, v_catalog.display_name, v_catalog.base_price,
      v_catalog.catalog_version, v_operation_id, v_transaction_id
    );
    insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
      source_type, source_id, operation_id)
    values (p_user_id, 'gems', -v_catalog.base_price, v_player.gems - v_catalog.base_price,
      'ticket_redemption', 'reward_ticket', v_ticket_id::text, v_operation_id);
    v_result := jsonb_build_object('transactionId', v_transaction_id,
      'ticketInstanceId', v_ticket_id, 'ticketKey', v_catalog.item_key,
      'paidAmount', v_catalog.base_price, 'currency', 'gems');

  else
    begin
      select * into v_ticket from public.player_reward_tickets
        where id = (v_payload ->> 'ticketInstanceId')::uuid and user_id = p_user_id for update;
    exception when invalid_text_representation then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
    end;
    if not found then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'TICKET_NOT_FOUND');
    end if;
    if v_ticket.status <> 'unused' then
      delete from private.command_operations where user_id = p_user_id and operation_id = v_operation_id;
      return jsonb_build_object('ok', false, 'errorCode', 'TICKET_ALREADY_USED');
    end if;
    select * into v_catalog from public.item_catalog where item_key = v_ticket.ticket_key;
    if v_type = 'USE_REWARD_TICKET' then
      update public.player_reward_tickets set status = 'used', used_at = now(), updated_at = now()
        where id = v_ticket.id;
      insert into public.economy_transactions(id, user_id, operation_id, transaction_type,
        item_key, ticket_id, item_name_snapshot, catalog_version_snapshot, detail_snapshot)
      values (v_transaction_id, p_user_id, v_operation_id, 'use_reward_ticket',
        v_ticket.ticket_key, v_ticket.id, v_ticket.name_snapshot, v_ticket.catalog_version_snapshot,
        jsonb_build_object('issuedAt', v_ticket.issued_at));
      v_result := jsonb_build_object('transactionId', v_transaction_id,
        'ticketInstanceId', v_ticket.id, 'status', 'used');
    else
      update public.player_states set gems = gems + v_ticket.gem_cost_snapshot, updated_at = now()
        where user_id = p_user_id;
      update public.player_reward_tickets set status = 'reversed', reversed_at = now(), updated_at = now()
        where id = v_ticket.id;
      insert into public.economy_transactions(id, user_id, operation_id, transaction_type,
        item_key, ticket_id, currency_type, currency_delta, base_price_snapshot,
        paid_amount_snapshot, item_name_snapshot, catalog_version_snapshot,
        reversal_of_transaction_id, detail_snapshot)
      values (v_transaction_id, p_user_id, v_operation_id, 'reverse_reward_ticket',
        v_ticket.ticket_key, v_ticket.id, 'gems', v_ticket.gem_cost_snapshot,
        v_ticket.gem_cost_snapshot, v_ticket.gem_cost_snapshot, v_ticket.name_snapshot,
        v_ticket.catalog_version_snapshot, v_ticket.acquisition_transaction_id,
        jsonb_build_object('refundFromSnapshot', true));
      insert into public.resource_ledger(user_id, resource_type, delta, balance_after, reason,
        source_type, source_id, operation_id)
      values (p_user_id, 'gems', v_ticket.gem_cost_snapshot,
        v_player.gems + v_ticket.gem_cost_snapshot, 'ticket_refund',
        'reward_ticket', v_ticket.id::text, v_operation_id);
      v_result := jsonb_build_object('transactionId', v_transaction_id,
        'ticketInstanceId', v_ticket.id, 'status', 'reversed',
        'refundedGems', v_ticket.gem_cost_snapshot);
    end if;
  end if;

  v_completed := private.phase4_complete_operation(
    p_user_id, v_operation_id,
    jsonb_build_object('operationId', v_operation_id, 'result', v_result, 'serverTimestamp', now())
  );
  if v_completed ->> 'ok' <> 'true' then return v_completed; end if;
  v_operation_version := (v_completed ->> 'repositoryVersion')::bigint;
  return v_completed || jsonb_build_object(
    'operationRepositoryVersion', v_operation_version,
    'state', private.phase4b_state(p_user_id) || private.phase5b_economy_state(p_user_id),
    'serverTimestamp', now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_achievement_reward_once()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.reward_granted_at is not null and (
    new.reward_granted_at is distinct from old.reward_granted_at
    or new.reward_operation_id is distinct from old.reward_operation_id
  ) then
    raise exception using errcode = '23514', message = 'ACHIEVEMENT_REWARD_ALREADY_RECORDED';
  end if;
  if old.reward_state = 'reversed' and new.reward_state <> 'reversed' then
    raise exception using errcode = '23514', message = 'ACHIEVEMENT_REWARD_REVERSAL_FINAL';
  end if;
  return new;
end;
$function$

