$function$

CREATE OR REPLACE FUNCTION private.guard_habit_event_reversal_once()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if row(
    new.id, new.user_id, new.business_date, new.habit_kind, new.system_key,
    new.custom_habit_id, new.direction, new.title_snapshot, new.policy_snapshot,
    new.definition_version, new.source_operation_id, new.occurred_at
  ) is distinct from row(
    old.id, old.user_id, old.business_date, old.habit_kind, old.system_key,
    old.custom_habit_id, old.direction, old.title_snapshot, old.policy_snapshot,
    old.definition_version, old.source_operation_id, old.occurred_at
  ) then
    raise exception using errcode = '23514', message = 'HABIT_EVENT_FACT_IMMUTABLE';
  end if;
  if old.reversed_at is not null and row(
    new.reversed_at, new.reversed_by_operation_id, new.reversal_reason
  ) is distinct from row(
    old.reversed_at, old.reversed_by_operation_id, old.reversal_reason
  ) then
    raise exception using errcode = '23514', message = 'HABIT_EVENT_ALREADY_REVERSED';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.initialize_member_profile(p_user_id uuid, p_command jsonb, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_operation_id text := coalesce(p_command ->> 'operationId', '');
  v_command_type text := coalesce(p_command ->> 'type', '');
  v_adventurer_name text := btrim(coalesce(p_command #>> '{payload,adventurerName}', ''));
  v_request_hash text := encode(
    extensions.digest(convert_to(p_command::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_inserted_count bigint := 0;
  v_profile_inserted_count bigint := 0;
  v_existing private.command_operations%rowtype;
  v_profile public.profiles%rowtype;
  v_root public.member_game_roots%rowtype;
  v_result jsonb;
begin
  if p_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'errorCode', 'AUTH_REQUIRED',
      'retryable', false,
      'operationId', null
    );
  end if;

  if p_command is null
    or jsonb_typeof(p_command) <> 'object'
    or coalesce(p_command ->> 'contractVersion', '') <> '1'
    or v_command_type <> 'INITIALIZE_MEMBER_PROFILE'
    or v_operation_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'
    or jsonb_typeof(p_command -> 'payload') <> 'object'
    or char_length(v_adventurer_name) not between 2 and 16
    or v_adventurer_name !~ '^[[:alnum:]]+$'
  then
    return jsonb_build_object(
      'ok', false,
      'errorCode', 'INVALID_PAYLOAD',
      'retryable', false,
      'operationId', nullif(v_operation_id, '')
    );
  end if;

  insert into private.command_operations (
    user_id,
    operation_id,
    command_type,
    request_hash,
    status
  ) values (
    p_user_id,
    v_operation_id,
    v_command_type,
    v_request_hash,
    'pending'
  )
  on conflict (user_id, operation_id) do nothing;

  get diagnostics v_inserted_count = row_count;

  select *
    into v_existing
    from private.command_operations
   where user_id = p_user_id
     and operation_id = v_operation_id
   for update;

  if v_inserted_count = 0 then
    if v_existing.request_hash <> v_request_hash
      or v_existing.command_type <> v_command_type
    then
      return jsonb_build_object(
        'ok', false,
        'errorCode', 'OPERATION_ID_REUSED',
        'retryable', false,
        'operationId', v_operation_id
      );
    end if;

    if v_existing.status = 'completed' and v_existing.result is not null then
      return v_existing.result || jsonb_build_object('duplicate', true);
    end if;

    return jsonb_build_object(
      'ok', false,
      'errorCode', 'OPERATION_IN_PROGRESS',
      'retryable', true,
      'operationId', v_operation_id
    );
  end if;

  select *
    into v_root
    from public.member_game_roots
   where user_id = p_user_id
   for update;

  if p_expected_version is not null
    and p_expected_version <> coalesce(v_root.repository_version, 0)
  then
    delete from private.command_operations
     where user_id = p_user_id
       and operation_id = v_operation_id;

    return jsonb_build_object(
      'ok', false,
      'errorCode', 'VERSION_CONFLICT',
      'retryable', true,
      'operationId', v_operation_id,
      'currentVersion', coalesce(v_root.repository_version, 0)
    );
  end if;

  insert into public.profiles (user_id, adventurer_name)
  values (p_user_id, v_adventurer_name)
  on conflict (user_id) do nothing;

  get diagnostics v_profile_inserted_count = row_count;

  insert into public.member_game_roots (user_id, repository_version)
  values (p_user_id, 0)
  on conflict (user_id) do nothing;

  update public.member_game_roots
     set repository_version = repository_version + 1,
         updated_at = now()
   where user_id = p_user_id
   returning * into v_root;

  select *
    into v_profile
    from public.profiles
   where user_id = p_user_id;

  v_result := jsonb_build_object(
    'ok', true,
    'operationId', v_operation_id,
    'repositoryVersion', v_root.repository_version,
    'duplicate', false,
    'serverTimestamp', now(),
    'result', jsonb_build_object(
      'initialized', true,
      'profileCreated', v_profile_inserted_count = 1
    ),
    'state', jsonb_build_object(
      'meta', jsonb_build_object(
        'repositoryVersion', v_root.repository_version,
        'operations', jsonb_build_array()
      ),
      'member', jsonb_build_object(
        'adventurerName', v_profile.adventurer_name,
        'onboardingStatus', v_profile.onboarding_status,
        'createdAt', v_profile.created_at,
        'updatedAt', v_profile.updated_at
      )
    )
  );

  update private.command_operations
     set status = 'completed',
         result = v_result,
         completed_at = now()
   where user_id = p_user_id
     and operation_id = v_operation_id;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.phase4_complete_operation(p_user_id uuid, p_operation_id text, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_operation private.command_operations%rowtype;
  v_root public.member_game_roots%rowtype;
  v_player public.player_states%rowtype;
  v_version bigint;
  v_result jsonb;
begin
  if p_user_id is null or p_operation_id is null or p_result is null
    or jsonb_typeof(p_result) <> 'object' then
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
  end if;

  select * into v_operation from private.command_operations
  where user_id = p_user_id and operation_id = p_operation_id for update;
  if not found then return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND'); end if;
  if v_operation.status = 'completed' then
    return coalesce(v_operation.result, '{}'::jsonb)
      || jsonb_build_object('ok', true, 'duplicate', true);
  end if;

  select * into v_root from public.member_game_roots
  where user_id = p_user_id for update;
  if not found then return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND'); end if;
  select * into v_player from public.player_states
  where user_id = p_user_id for update;
  if not found then return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND'); end if;

  update public.member_game_roots
  set repository_version = repository_version + 1, updated_at = now()
  where user_id = p_user_id
  returning repository_version into v_version;

  v_result := p_result || jsonb_build_object(
    'ok', true, 'duplicate', false, 'repositoryVersion', v_version
  );
  update private.command_operations
  set status = 'completed', result = v_result, completed_at = now()
  where user_id = p_user_id and operation_id = p_operation_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.phase4_reserve_operation(p_user_id uuid, p_operation_id text, p_command_type text, p_request_hash text, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_inserted integer;
  v_operation private.command_operations%rowtype;
  v_root public.member_game_roots%rowtype;
  v_player public.player_states%rowtype;
begin
  if p_user_id is null or p_operation_id is null or p_request_hash is null
    or p_command_type not in (
      'REPORT_HABIT_EVENT', 'REVERSE_HABIT_EVENT', 'SUBMIT_DAILY_ENTRY',
      'PURCHASE_ITEM', 'USE_ITEM', 'EQUIP_ITEM', 'UNEQUIP_ITEM',
      'REDEEM_REWARD_TICKET', 'USE_REWARD_TICKET', 'REVERSE_REWARD_TICKET'
    )
    or p_expected_version is null or p_expected_version < 0 then
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
  end if;

  insert into private.command_operations(user_id, operation_id, command_type, request_hash, status)
  values (p_user_id, p_operation_id, p_command_type, p_request_hash, 'pending')
  on conflict (user_id, operation_id) do nothing;
  get diagnostics v_inserted = row_count;

  select * into v_operation
  from private.command_operations
  where user_id = p_user_id and operation_id = p_operation_id
  for update;

  if v_inserted = 0 then
    if v_operation.command_type <> p_command_type or v_operation.request_hash <> p_request_hash then
      return jsonb_build_object('ok', false, 'errorCode', 'OPERATION_ID_REUSED');
    end if;
    if v_operation.status = 'completed' then
      return coalesce(v_operation.result, '{}'::jsonb)
        || jsonb_build_object('ok', true, 'duplicate', true);
    end if;
    return jsonb_build_object('ok', false, 'errorCode', 'OPERATION_IN_PROGRESS');
  end if;

  -- Fixed per-user lock order: operation receipt -> aggregate root -> player state.
  -- The locked root serializes all Phase 4/5 mutations before future economy rows are touched.
  select * into v_root from public.member_game_roots
  where user_id = p_user_id for update;
  if not found then
    delete from private.command_operations where user_id = p_user_id and operation_id = p_operation_id;
    return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND');
  end if;

  select * into v_player from public.player_states
  where user_id = p_user_id for update;
  if not found then
    delete from private.command_operations where user_id = p_user_id and operation_id = p_operation_id;
    return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND');
  end if;

  if v_root.repository_version <> p_expected_version then
    delete from private.command_operations where user_id = p_user_id and operation_id = p_operation_id;
    return jsonb_build_object(
      'ok', false, 'errorCode', 'VERSION_CONFLICT',
      'currentVersion', v_root.repository_version
    );
  end if;

  return jsonb_build_object(
    'ok', true, 'duplicate', false, 'reserved', true,
    'repositoryVersion', v_root.repository_version
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.phase4b_operation_receipt(p_user_id uuid, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_operation private.command_operations%rowtype;
  v_operation_id text := p_command ->> 'operationId';
  v_command_type text := p_command ->> 'type';
  v_request_hash text;
  v_current_version bigint;
  v_operation_version bigint;
begin
  if p_user_id is null or p_command is null or jsonb_typeof(p_command) <> 'object'
    or v_command_type not in ('REPORT_HABIT_EVENT', 'REVERSE_HABIT_EVENT', 'SUBMIT_DAILY_ENTRY')
    or p_command ->> 'contractVersion' <> '1'
    or v_operation_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    return jsonb_build_object('ok', false, 'errorCode', 'INVALID_PAYLOAD');
  end if;

  v_request_hash := encode(extensions.digest(convert_to(p_command::text, 'UTF8'), 'sha256'), 'hex');
  select * into v_operation from private.command_operations
    where user_id = p_user_id and operation_id = v_operation_id;
  if not found then return jsonb_build_object('ok', true, 'duplicate', false); end if;
  if v_operation.command_type <> v_command_type or v_operation.request_hash <> v_request_hash then
    return jsonb_build_object('ok', false, 'errorCode', 'OPERATION_ID_REUSED');
  end if;
  if v_operation.status <> 'completed' or v_operation.result is null then
    return jsonb_build_object('ok', false, 'errorCode', 'OPERATION_IN_PROGRESS', 'retryable', true);
  end if;

  select repository_version into v_current_version
    from public.member_game_roots where user_id = p_user_id;
  if v_current_version is null then return jsonb_build_object('ok', false, 'errorCode', 'NOT_FOUND'); end if;
  v_operation_version := coalesce((v_operation.result ->> 'repositoryVersion')::bigint, v_current_version);
  return v_operation.result || jsonb_build_object(
    'ok', true, 'duplicate', true, 'operationId', v_operation_id,
    'operationRepositoryVersion', v_operation_version,
    'repositoryVersion', v_current_version,
    'state', private.phase4b_state(p_user_id), 'serverTimestamp', now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.phase5_guard_equipment_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_item public.item_catalog%rowtype;
begin
  select * into v_item from public.item_catalog where item_key = new.item_key;
  if not found or not v_item.equippable or v_item.equipment_slot <> new.slot then
    raise exception 'PHASE5_INVALID_EQUIPMENT_SLOT';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.phase5_guard_inventory_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_item public.item_catalog%rowtype;
begin
  select * into v_item from public.item_catalog where item_key = new.item_key;
  if not found or v_item.item_type = 'reward_ticket' then
    raise exception 'PHASE5_INVALID_INVENTORY_ITEM';
  end if;
  if v_item.item_type = 'potion' and new.quantity > v_item.max_stack then
    raise exception 'PHASE5_INVENTORY_STACK_LIMIT';
  end if;
  if v_item.item_type in ('weapon', 'armor', 'pet') and new.quantity <> 1 then
    raise exception 'PHASE5_EQUIPMENT_MUST_BE_UNIQUE';
  end if;
  return new;
end;
$function$

